/// `ParameterType`.
#[derive(Debug, Clone, PartialEq)]
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
pub struct Parameter {
    /// `Name` attribute, 1..1.
    pub name: String,
    /// `choice of 6` element, 1..1.
    pub choice: ParameterChoice,
}

impl Parameter {
    /// Event-code arithmetic of this type's content model.
    const SHAPE: Shape = Shape {
        prod_before: &[0, 1, 7],
        width: &[1, 3, 1],
        repeat_width: &[0, 0],
        min: &[1, 1],
        max: &[1, 1],
    };
}

impl Parameter {
    /// Writes this element's content and its end event.
    ///
    /// The parent writes the start event; this writes everything
    /// inside it, so the two compose without either knowing the
    /// other's grammar.
    pub fn encode_body(&self, e: &mut Encoder<'_>) -> ExiResult<()> {
        e.enter()?;
        let mut w = SeqWriter::new(Self::SHAPE);
        // Name (1..1)
        {
            let item = &self.name;
            w.start(e, 0, 0)?;
            e.string(ValueCtx(112), item, Lengths::max(80))?;
            w.finish(0, 1);
        }
        // choice of 6 (1..1)
        {
            let item = &self.choice;
            match item {
                ParameterChoice::BoolValue(value) => {
                    w.start_branch(e, 1, 0, 0)?;
                    e.event(0, SIMPLE_WIDTH)?; // CH
                    e.boolean(*value)?;
                    e.event(0, SIMPLE_WIDTH)?; // EE
                }
                ParameterChoice::ByteValue(value) => {
                    w.start_branch(e, 1, 0, 1)?;
                    e.event(0, SIMPLE_WIDTH)?; // CH
                    e.restricted(i64::from(*value), -128, 127)?;
                    e.event(0, SIMPLE_WIDTH)?; // EE
                }
                ParameterChoice::ShortValue(value) => {
                    w.start_branch(e, 1, 0, 2)?;
                    e.event(0, SIMPLE_WIDTH)?; // CH
                    e.int(i64::from(*value))?;
                    e.event(0, SIMPLE_WIDTH)?; // EE
                }
                ParameterChoice::IntValue(value) => {
                    w.start_branch(e, 1, 0, 3)?;
                    e.event(0, SIMPLE_WIDTH)?; // CH
                    e.int(i64::from(*value))?;
                    e.event(0, SIMPLE_WIDTH)?; // EE
                }
                ParameterChoice::RationalNumber(value) => {
                    w.start_branch(e, 1, 0, 4)?;
                    value.encode_body(e)?;
                }
                ParameterChoice::FiniteString(value) => {
                    w.start_branch(e, 1, 0, 5)?;
                    e.event(0, SIMPLE_WIDTH)?; // CH
                    e.string(ValueCtx(228), value, Lengths::max(80))?;
                    e.event(0, SIMPLE_WIDTH)?; // EE
                }
            }
            w.finish(1, 1);
        }
        w.end(e)?;
        e.leave();
        Ok(())
    }
}

impl Parameter {
    /// Reads this element's content, up to and including its end
    /// event. The parent has already read the start event.
    pub fn decode_body(d: &mut Decoder<'_>) -> ExiResult<Self> {
        d.enter()?;
        let mut r = SeqReader::new(Self::SHAPE);
        let mut f_0 = None;
        let mut f_1 = None;
        loop {
            match r.next(d)? {
                Step::End => break,
                Step::Item { index: 0, .. } => {
                    let value = d.string(ValueCtx(112), Lengths::max(80))?;
                    f_0 = Some(value);
                }
                Step::Item { index: 1, branch, .. } => {
                    let value = match branch {
                        0 => {
                            d.expect_event(0, SIMPLE_WIDTH)?; // CH
                            let value = d.boolean()?;
                            d.expect_event(0, SIMPLE_WIDTH)?; // EE
                            ParameterChoice::BoolValue(value)
                        }
                        1 => {
                            d.expect_event(0, SIMPLE_WIDTH)?; // CH
                            let value = i8::try_from(d.restricted(-128, 127)?)
                                .map_err(|_| ExiError::ValueOutOfRange)?;
                            d.expect_event(0, SIMPLE_WIDTH)?; // EE
                            ParameterChoice::ByteValue(value)
                        }
                        2 => {
                            d.expect_event(0, SIMPLE_WIDTH)?; // CH
                            let value =
                                i16::try_from(d.int()?).map_err(|_| ExiError::IntegerOverflow)?;
                            d.expect_event(0, SIMPLE_WIDTH)?; // EE
                            ParameterChoice::ShortValue(value)
                        }
                        3 => {
                            d.expect_event(0, SIMPLE_WIDTH)?; // CH
                            let value =
                                i32::try_from(d.int()?).map_err(|_| ExiError::IntegerOverflow)?;
                            d.expect_event(0, SIMPLE_WIDTH)?; // EE
                            ParameterChoice::IntValue(value)
                        }
                        4 => {
                            let value = super::common::RationalNumber::decode_body(d)?;
                            ParameterChoice::RationalNumber(value)
                        }
                        5 => {
                            d.expect_event(0, SIMPLE_WIDTH)?; // CH
                            let value = d.string(ValueCtx(228), Lengths::max(80))?;
                            d.expect_event(0, SIMPLE_WIDTH)?; // EE
                            ParameterChoice::FiniteString(value)
                        }
                        _ => return Err(ExiError::UnknownEventCode),
                    };
                    f_1 = Some(value);
                }
                Step::Item { .. } => return Err(ExiError::UnknownEventCode),
            }
        }
        d.leave();
        Ok(Self {
            name: f_0.ok_or(ExiError::MissingElement)?,
            choice: f_1.ok_or(ExiError::MissingElement)?,
        })
    }
}

